package com.sponsormatch.controller;
import com.sponsormatch.dto.CampaignDtos.*;import com.sponsormatch.service.CampaignService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/campaigns") @RequiredArgsConstructor public class CampaignController {private final CampaignService service;@PostMapping public CampaignResponse create(@AuthenticationPrincipal Long id,@Valid @RequestBody CampaignRequest r){return service.create(id,r);}@GetMapping("/my") public List<CampaignResponse> mine(@AuthenticationPrincipal Long id){return service.mine(id);}@GetMapping("/{id}") public CampaignResponse get(@PathVariable Long id){return service.get(id);}@PutMapping("/{id}") public CampaignResponse update(@AuthenticationPrincipal Long uid,@PathVariable Long id,@Valid @RequestBody CampaignRequest r){return service.update(uid,id,r);}@DeleteMapping("/{id}") public void delete(@AuthenticationPrincipal Long uid,@PathVariable Long id){service.delete(uid,id);}}
